css:
.container {
  width: 7em;
  height: 7em;
  position: relative;
}
.button {
  position: absolute;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  border: 4px solid #041e42;
  background-color: transparent;
  background-image: linear-gradient(145deg, #0a2a5e, #1e4d8c);
  box-sizing: border-box;
  box-shadow:
    inset 2px 2px 0 #2c5aa0,
    inset -2px -2px 0px #041e42;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: border-color 3s ease;
}
.container input {
  display: none;
}
.button::before {
  position: absolute;
  content: "";
  width: 7.25em;
  height: 7.25em;
  border-radius: inherit;
  background-color: transparent;
  background-image: linear-gradient(145deg, #0a2a5e, #2c5aa0);
  z-index: -1;
  box-shadow:
    11px 11px 22px #041e42,
    -11px -11px 22px #3a78d0;
}
.button .icon {
  width: 60px;
  height: 60px;
  display: inline-block;
}
.button .icon svg {
  height: 100%;
  width: 100%;
  fill: #a0c8ff;
  transition: fill 1s ease;
}
.container input:checked + .button {
  box-shadow:
    inset -2px -2px 0 #2c5aa0,
    inset 2px 2px 0 #041e42;
  border-color: rgba(255, 0, 0, 1);
}
.container input:checked + .button .icon svg {
  fill: rgb(255, 0, 0);
}
